// import { get_expense_forms } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";

// import { update_expense_forms } from "@/graphql/mutations.js";

import SnackBar from "@/components/SnackBar.vue";
export default {
  mixins: [get_all_org_users],
  components: {
    SnackBar
  },
  data() {
    return {
      addData: false,
      stepsSelected: [],
      rolesRM: false,
      loading: false,
      initiaorRM: null,
      initiaorCheck: null,
      teamMember: null,
      teamMemberSelected: "",
      SnackBarComponent: {},
      selectedData: [],
      flowSteps: [{
        selected: false,
        text: "Initiator"
      }, {
        selected: false,
        text: "Initiator's Reporting Manager"
      }, {
        selected: false,
        text: "Roles"
      }],
      finalArray: [],
      addedRecords: [],
      listSelected: [],
      roleSelected: "",
      itemSelIndex: 0,
      userList: [],
      workflowList: [],
      formObject: {},
      inputRecords: [],
      tableData: [],
      templete: [],
      search: ""
    };
  },
  async created() {
    this.$store.commit("Setnamesearch", this.search);
    await this.get_all_org_users();
    await this.fetch_users();
    // await this.get_initiated_expense();
  },
  watch: {
    addData: {
      async handler() {
        // await this.get_all_org_users();
      }
    }
  },
  methods: {
    async save_expense_head() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(update_expense_forms, {
          input: {
            user_email_id: data.user.user_email_id,
            workflow_id: this.tableData.workflow_id,
            workflow_approval_steps: JSON.stringify(this.addedRecords)
          }
        }));
        var response = JSON.parse(result.data.update_expense_forms);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
          this.get_initiated_expense();
          this.$refs.form.reset();
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
        this.loading = false;
      }
    },
    fetch_users() {
      this.userList = [];
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userList.push({
            label: element.full_user_name,
            value: element.user_id
          });
        }
      });
      this.userList.sort((a, b) => a.label.localeCompare(b.label));
    },
    delete_record(val) {
      this.addedRecords.splice(val, 1);
      this.stepsSelected = [];
      this.initiaorRM = null;
      this.initiaorCheck = null;
      this.rolesRM = false;
      this.roleSelected = "";
    },
    close_dialog() {
      this.addData = false;
      this.initiaorRM = null;
      this.initiaorCheck = null;
      this.rolesRM = false;
      this.roleSelected = "";
      this.inputRecords = [];
      this.$refs.form.reset();
      this.$refs.form.resetValidation();
    },
    add_row(value) {
      this.inputRecords = [];
      this.teamMember = null;
      this.initiaorCheck = null;
      this.initiaorRM = null;
      this.itemSelIndex = value;
      this.addData = true;
    },
    add_dialog() {
      this.inputRecords = [];
      this.teamMember = null;
      this.initiaorCheck = null;
      this.initiaorRM = null;
      this.addData = true;
    },
    add_items() {
      var newArray = this.addedRecords;
      //   var count = 0;
      if (this.$refs.form.validate()) {
        this.addData = false;
        this.initiaorRM = null;
        this.initiaorCheck = null;
        this.rolesRM = false;
        this.roleSelected = "";
        this.teamMemberSelected = "";
        this.teamMember = null;
        newArray.splice(this.itemSelIndex + 1, 0, this.finalArray[0]);

        // var array3 = newArray.push({
        //   stepCount: count++,
        // });
        // this.addedRecords = [...newArray, ...this.finalArray];
        // console.log(newArray);
        this.addedRecords = newArray;
        this.stepsSelected = [];
        this.$refs.form.reset();
        this.$refs.form.resetValidation();
      }
    },
    get_input(index) {
      this.inputRecords = [];
      if (index == 2 && index != undefined) {
        // this.inputRecords = this.tableData.workflow_approval_steps;
        // var count=

        this.inputRecords.push({
          step_no: this.addedRecords.length + 1,
          name: this.teamMemberSelected.label,
          user_id: this.teamMemberSelected.value,
          user_type: "team_member",
          workflow_template: this.templete
        });
        this.teamMember = "member_team";
        this.initiaorCheck = null;
        this.initiaorRM = null;
        this.rolesRM = false;
      }
      this.finalArray = this.inputRecords;
    },
    async get_initiated_expense() {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(get_expense_forms, {
          input: {
            user_email_id: data.user.user_email_id,
            organization_id: data.organization.organization_id
          }
        }));
        var response = JSON.parse(result.data.get_expense_forms);
        if (response.Status == "SUCCESS") {
          this.templete = response.data[0].workflow_template;
          this.tableData = response.data[0];
          this.addedRecords = this.tableData.workflow_approval_steps;
          if (this.addedRecords.length > 0) {
            for (let s = 0; s < this.addedRecords.length; s++) {
              let name = this.orgUsers.filter(x => x.user_id == this.addedRecords[s].user_id);
              this.addedRecords[s].name = name.length > 0 ? name[0].full_user_name : "N/A";
            }
          }
        } else {
          this.tableData = [];
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
